@Slf4j
public class SnailManModeOverlay extends Overlay {
    private static final int MAX_DRAW_DISTANCE = 32;

    private final Client client;
    private final SnailManModeConfig config;
    private final SnailManModePlugin plugin;
    private final boolean developerMode;

    BufferedImage snailShell = null;

    @Inject
    private SnailManModeOverlay(Client client, SnailManModeConfig config, SnailManModePlugin plugin, @Named("developerMode") boolean developerMode) {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        this.developerMode = developerMode;

        this.setPosition(OverlayPosition.DYNAMIC);
        this.setPriority(OverlayPriority.LOW);
        this.setLayer(OverlayLayer.ABOVE_SCENE);
    }

    private void renderTransports(Graphics2D graphics) {
        for (WorldPoint a : this.plugin.pathfinderConfig.getTransports().keySet()) {
            this.drawTransport(graphics, a);

            java.awt.Point ca = this.tileCenter(a);

            if (ca == null) {
                continue;
            }

            for (Transport t : this.plugin.pathfinderConfig.getTransports().get(a)) {
                WorldPoint b = t.getOrigin();
                java.awt.Point cb = this.tileCenter(b);

                if (cb != null) {
                    graphics.drawLine(ca.x, ca.y, cb.x, cb.y);
                }
            }

            StringBuilder s = new StringBuilder();
            for (Transport t : this.plugin.pathfinderConfig.getTransports().get(a)) {
                WorldPoint b = t.getDestination();
                if (b.getPlane() > a.getPlane()) {
                    s.append("+");
                } else if (b.getPlane() < a.getPlane()) {
                    s.append("-");
                } else {
                    s.append("=");
                }
            }
            graphics.setColor(Color.WHITE);
            graphics.drawString(s.toString(), ca.x, ca.y);
        }
    }

    private java.awt.Point tileCenter(WorldPoint b) {
        if (b.getPlane() != this.client.getPlane()) {
            return null;
        }

        LocalPoint lp = LocalPoint.fromWorld(this.client, b);
        if (lp == null) {
            return null;
        }

        Polygon poly = Perspective.getCanvasTilePoly(this.client, lp);
        if (poly == null) {
            return null;
        }

        int cx = poly.getBounds().x + poly.getBounds().width / 2;
        int cy = poly.getBounds().y + poly.getBounds().height / 2;
        return new java.awt.Point(cx, cy);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (this.developerMode) this.renderTransports(graphics);

        WorldPoint snailPoint = this.plugin.getSnailWorldPoint();
        WorldPoint playerLocation = this.client.getLocalPlayer().getWorldLocation();

        if (this.developerMode && this.plugin.pathfinder != null) {
            List<WorldPoint> path = this.plugin.pathfinder.getPath();
            for (WorldPoint point : path) {
                this.drawTile(graphics, point, Color.GREEN, new BasicStroke((float) 2));
            }
        }

        long drawDistance = this.config.drawDistance();

        if (snailPoint.distanceTo(playerLocation) >= drawDistance) {
            return null;
        }

        if (this.config.drawTile()) {
            this.drawTile(graphics, snailPoint, this.config.tileColor(), new BasicStroke((float) 2));
        }
        if (this.config.visualMode() == SnailManModeConfig.SnailVisualMode.SPRITE) {
            this.drawImg(graphics, snailPoint);
        }
        return null;
    }

    private void drawTile(Graphics2D graphics, WorldPoint point, Color color, Stroke borderStroke) {

        LocalPoint lp = LocalPoint.fromWorld(this.client, point);
        if (lp == null) {
            return;
        }

        Polygon poly = Perspective.getCanvasTilePoly(this.client, lp);
        if (poly != null) {
            OverlayUtil.renderPolygon(graphics, poly, color, new Color(0, 0, 0, 1), borderStroke);
        }
    }

    private void drawImg(Graphics2D graphics, WorldPoint point) {
        LocalPoint lp = LocalPoint.fromWorld(this.client, point);
        if (lp == null) {
            return;
        }

        BufferedImage snailShell = this.getSnailImage();
//        snailShell = ImageUtil.resizeImage(snailShell, snailShell.getWidth() * 10, snailShell.getHeight() * 10);
        Point canvasImageLocation = Perspective.getCanvasImageLocation(this.client, lp, snailShell, 75);

        if (canvasImageLocation == null) {
            return;
        }

        OverlayUtil.renderImageLocation(graphics, canvasImageLocation, snailShell);
    }

    private void drawTransport(Graphics2D graphics, WorldPoint point) {
        if (point.getPlane() != this.client.getPlane()) {
            return;
        }

        LocalPoint lp = LocalPoint.fromWorld(this.client, point);
        if (lp == null) {
            return;
        }

        Polygon poly = Perspective.getCanvasTilePoly(this.client, lp);
        if (poly == null) {
            return;
        }

        graphics.setColor(Color.GREEN);
        graphics.fill(poly);
    }

    private BufferedImage getSnailImage() {
        if (this.snailShell == null) {
            this.snailShell = ImageUtil.loadImageResource(this.getClass(), "/snail_shell.png");
        }
        return this.snailShell;
    }
}

package com.idyl.snailman.pathfinder;

import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.cache.Weigher;
import com.google.common.util.concurrent.UncheckedExecutionException;
import com.idyl.snailman.Util;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.zip.GZIPInputStream;

public abstract class SplitFlagMap {
    private static final int MAXIMUM_SIZE = 20 * 1024 * 1024;
    private final int regionSize;
    private final LoadingCache<Position, FlagMap> regionMaps;
    private final int flagCount;

    public SplitFlagMap(int regionSize, Map<Position, byte[]> compressedRegions, int flagCount) {
        this.regionSize = regionSize;
        this.flagCount = flagCount;
        this.regionMaps = CacheBuilder
            .newBuilder()
            .weigher((Weigher<Position, FlagMap>) (k, v) -> v.flags.size() / 8)
            .maximumWeight(MAXIMUM_SIZE)
            .build(CacheLoader.from(position -> {
                byte[] compressedRegion = compressedRegions.get(position);

                if (compressedRegion == null) {
                    return new FlagMap(position.x * regionSize, position.y * regionSize, (position.x + 1) * regionSize - 1, (position.y + 1) * regionSize - 1, this.flagCount);
                }

                try (InputStream in = new GZIPInputStream(new ByteArrayInputStream(compressedRegion))) {
                    return new FlagMap(Util.readAllBytes(in), this.flagCount);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }));
    }

    public boolean get(int x, int y, int z, int flag) {
        try {
            return this.regionMaps.get(new Position(x / this.regionSize, y / this.regionSize)).get(x, y, z, flag);
        } catch (ExecutionException e) {
            throw new UncheckedExecutionException(e);
        }
    }

    public static class Position {
        public final int x;
        public final int y;

        public Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Position &&
                ((Position) o).x == this.x &&
                ((Position) o).y == this.y;
        }

        @Override
        public int hashCode() {
            return this.x * 31 + this.y;
        }

        @Override
        public String toString() {
            return "(" + this.x + ", " + this.y + ")";
        }
    }
}

package com.idyl.snailman.pathfinder;

import com.idyl.snailman.Transport;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.*;

@Slf4j
public class Pathfinder implements Runnable {
    @Getter
    private final WorldPoint start;
    @Getter
    private final WorldPoint target;
    private final PathfinderConfig config;

    private final List<Node> boundary = new LinkedList<>();
    private final Set<WorldPoint> visited = new HashSet<>();

    public boolean isComplete;

    @Getter
    private List<WorldPoint> path = new ArrayList<>();
    @Getter
    private boolean done = false;

    public Pathfinder(PathfinderConfig config, WorldPoint start, WorldPoint target, List<WorldPoint> existingPath) {
        this.config = config;
        this.start = start;
        this.target = target;

        this.isComplete = false;

        if (existingPath != null) {
            Node prev = null;
            boolean foundStart = false;
            for (int i = 0; i < existingPath.size(); i++) {
                WorldPoint point = existingPath.get(i);

                if (!point.equals(start) && !foundStart) continue;
                foundStart = true;

                Node n = new Node(existingPath.get(i), prev);
                this.boundary.add(n);
                prev = n;
            }
        }

        new Thread(this).start();
    }

    public static void writeTransportToFile(String transport) {
        try {
            Files.write(Paths.get("src/main/resources/transports.txt"), transport.concat("\n").getBytes(), StandardOpenOption.APPEND);
        } catch (IOException e) {
            log.error("Failed to write transport to file", e);
        }
    }

    private void addNeighbor(Node node, WorldPoint neighbor) {
        if (!this.visited.add(neighbor)) {
            return;
        }
        this.boundary.add(new Node(neighbor, node));
    }

    private void addNeighbors(Node node) {
        for (WorldPoint neighbor : this.config.getMap().getNeighbors(node.position)) {
            this.addNeighbor(node, neighbor);
        }

        for (Transport transport : this.config.getTransports().getOrDefault(node.position, new ArrayList<>())) {
            this.addNeighbor(node, transport.getDestination());
        }
    }

    @Override
    public void run() {
        this.boundary.add(new Node(this.start, null));

        Node nearest = this.boundary.get(0);
        int bestDistance = Integer.MAX_VALUE;
        Instant cutoffTime = Instant.now().plus(PathfinderConfig.CALCULATION_CUTOFF);
        long startTime = Instant.now().toEpochMilli();

        while (!this.boundary.isEmpty()) {
            Node node = this.boundary.remove(0);

            if (node.position.equals(this.target)) {
                this.path = node.getPath();
                log.debug("Found best path.");
                this.isComplete = true;
                break;
            }

            int distance = node.position.distanceTo(this.target);
            if (distance < bestDistance) {
                this.path = node.getPath();
                nearest = node;
                bestDistance = distance;
                cutoffTime = Instant.now().plus(PathfinderConfig.CALCULATION_CUTOFF);
            }

            if (Instant.now().isAfter(cutoffTime)) {
                this.path = nearest.getPath();
                long elapsed = Instant.now().toEpochMilli() - startTime;
                break;
            }

            this.addNeighbors(node);
        }
        long elapsed = Instant.now().toEpochMilli() - startTime;
        log.debug("Finished calculation in {}ms", elapsed);

        this.done = true;
        this.boundary.clear();
        this.visited.clear();
    }
}

