        this.y = y;
    }
}

package com.idyl.snailman.pathfinder;

import java.nio.ByteBuffer;
import java.util.BitSet;

public class FlagMap {
    public static final int PLANE_COUNT = 4;
    public final int minX;
    public final int minY;
    public final int maxX;
    public final int maxY;
    protected final BitSet flags;
    private final int width;
    private final int height;
    private final int flagCount;

    public FlagMap(int minX, int minY, int maxX, int maxY, int flagCount) {
        this.minX = minX;
        this.minY = minY;
        this.maxX = maxX;
        this.maxY = maxY;
        this.flagCount = flagCount;
        this.width = (maxX - minX + 1);
        this.height = (maxY - minY + 1);
        this.flags = new BitSet(this.width * this.height * PLANE_COUNT * flagCount);
    }

    public FlagMap(byte[] bytes, int flagCount) {
        ByteBuffer buffer = ByteBuffer.wrap(bytes);
        this.minX = buffer.getInt();
        this.minY = buffer.getInt();
        this.maxX = buffer.getInt();
        this.maxY = buffer.getInt();
        this.flagCount = flagCount;
        this.width = (this.maxX - this.minX + 1);
        this.height = (this.maxY - this.minY + 1);
        this.flags = BitSet.valueOf(buffer);
    }

    public byte[] toBytes() {
        byte[] bytes = new byte[16 + this.flags.size()];
        ByteBuffer buffer = ByteBuffer.wrap(bytes);
        buffer.putInt(this.minX);
        buffer.putInt(this.minY);
        buffer.putInt(this.maxX);
        buffer.putInt(this.maxY);
        buffer.put(this.flags.toByteArray());
        return bytes;
    }

    public boolean get(int x, int y, int z, int flag) {
        if (x < this.minX || x > this.maxX || y < this.minY || y > this.maxY || z < 0 || z > PLANE_COUNT - 1) {
            return false;
        }

        return this.flags.get(this.index(x, y, z, flag));
    }

    public void set(int x, int y, int z, int flag, boolean value) {
        this.flags.set(this.index(x, y, z, flag), value);
    }

    private int index(int x, int y, int z, int flag) {
        if (x < this.minX || x > this.maxX || y < this.minY || y > this.maxY || z < 0 || z > PLANE_COUNT - 1 || flag < 0 || flag > this.flagCount - 1) {
            throw new IndexOutOfBoundsException(x + " " + y + " " + z);
        }

        return (z * this.width * this.height + (y - this.minY) * this.width + (x - this.minX)) * this.flagCount + flag;
    }
}

package com.idyl.snailman.pathfinder;

import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class Node {
    public final WorldPoint position;
    public final Node previous;

    public Node(WorldPoint position, Node previous) {
        this.position = position;
        this.previous = previous;
    }

    public List<WorldPoint> getPath() {
        List<WorldPoint> path = new LinkedList<>();
        Node node = this;

        while (node != null) {
            path.add(0, node.position);
            node = node.previous;
        }

        return new ArrayList<>(path);
    }
}

package com.idyl.snailman.pathfinder;

import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class CollisionMap extends SplitFlagMap {
    public CollisionMap(int regionSize, Map<Position, byte[]> compressedRegions) {
        super(regionSize, compressedRegions, 2);
    }

    public boolean n(int x, int y, int z) {
        return this.get(x, y, z, 0);
    }

    public boolean s(int x, int y, int z) {
        return this.n(x, y - 1, z);
    }

    public boolean e(int x, int y, int z) {
        return this.get(x, y, z, 1);
    }

    public boolean w(int x, int y, int z) {
        return this.e(x - 1, y, z);
    }

    private boolean ne(int x, int y, int z) {
        return this.n(x, y, z) && this.e(x, y + 1, z) && this.e(x, y, z) && this.n(x + 1, y, z);
    }

    private boolean nw(int x, int y, int z) {
        return this.n(x, y, z) && this.w(x, y + 1, z) && this.w(x, y, z) && this.n(x - 1, y, z);
    }

    private boolean se(int x, int y, int z) {
        return this.s(x, y, z) && this.e(x, y - 1, z) && this.e(x, y, z) && this.s(x + 1, y, z);
    }

    private boolean sw(int x, int y, int z) {
        return this.s(x, y, z) && this.w(x, y - 1, z) && this.w(x, y, z) && this.s(x - 1, y, z);
    }

    public boolean isBlocked(int x, int y, int z) {
        return !this.n(x, y, z) && !this.s(x, y, z) && !this.e(x, y, z) && !this.w(x, y, z);
    }

    public List<WorldPoint> getNeighbors(WorldPoint position) {
        int x = position.getX();
        int y = position.getY();
        int z = position.getPlane();

        List<WorldPoint> neighbors = new ArrayList<>();
        boolean[] traversable = new boolean[]{
            this.w(x, y, z), this.e(x, y, z), this.s(x, y, z), this.n(x, y, z), this.sw(x, y, z), this.se(x, y, z), this.nw(x, y, z), this.ne(x, y, z)
        };

        for (int i = 0; i < traversable.length; i++) {
            if (traversable[i]) {
                OrdinalDirection direction = OrdinalDirection.values()[i];
                neighbors.add(position.dx(direction.x).dy(direction.y));
            }
        }

        return neighbors;
    }
}

